package Accounts;
# Account balance lookups against an injected database handle.
use strict;
use warnings;

sub balance {
    my ($dbh, $account) = @_;
    return $dbh->selectall_arrayref("SELECT balance FROM accounts WHERE account = '$account'");
}

1;

use strict;
use warnings;
use Test::More;
use Accounts;

{
    package FixedDb;
    sub new { return bless {}, shift }
    sub selectall_arrayref { return [[25]] }
}

is_deeply(Accounts::balance(FixedDb->new, 'alice'), [[25]], 'returns rows');

done_testing();
